using System;using UnityEditor;
public static class DevelopmentSeparationInstall {
 static void Ensure(string p){if(AssetDatabase.IsValidFolder(p))return;int i=p.LastIndexOf('/');Ensure(p.Substring(0,i));AssetDatabase.CreateFolder(p.Substring(0,i),p.Substring(i+1));}
 static void Move(string from,string to){Ensure(System.IO.Path.GetDirectoryName(to).Replace((char)92,(char)47));if(!string.IsNullOrEmpty(AssetDatabase.AssetPathToGUID(to)))throw new Exception("Destination exists "+to);string error=AssetDatabase.MoveAsset(from,to);if(!string.IsNullOrEmpty(error))throw new Exception(error);}
 public static void Run(){const string root="Assets/Shioka/";Ensure(root+"Development/Runtime/UI");Ensure(root+"Tests/EditMode/Editor");Ensure(root+"Tests/PlayMode/Editor");AssetDatabase.StartAssetEditing();try{foreach(string name in new[]{"TrainingOverlay.ComparisonOptions.cs","TrainingOverlay.LocomotionOptions.cs","TrainingOverlay.DeveloperOptions.cs"})Move(root+"Runtime/Training/UI/"+name,root+"Development/Runtime/UI/"+name);foreach(string name in new[]{"CombatV01FormulaChecks.cs","InputFoundationChecks.cs","SkillDataChecks.cs"})Move(root+"Editor/Validation/"+name,root+"Tests/EditMode/Editor/"+name);foreach(string name in new[]{"InputLivePlayChecks.cs","InputV3Checks.cs","KeyConfigChecks.cs","MotionActionChecks.cs","LayoutPlayChecks.cs"})Move(root+"Editor/Validation/"+name,root+"Tests/PlayMode/Editor/"+name);}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();}
}
